command -v python3>/dev/null||{ echo python3_required;exit 127;};python3 -c 'import sys,json,math,os,time;f=sys.argv[1]if len(sys.argv)>1 else sys.argv[0];x=open(f,"rb").read()if os.path.exists(f)else sys.stdin.buffer.read();M=int(sys.argv[2])if len(sys.argv)>2 else 257;N=int(sys.argv[3])if len(sys.argv)>3 else 4096;P=[];n=2;exec("while len(P)<len(x)+96:\n r=int(math.isqrt(n))\n if n>1 and all(n%d for d in range(2,r+1)):P.append(n)\n n+=1");exec("def S(y):\n q=P[:len(y)]\n E=[b+1 for b in y]\n return sum(e*math.log(p)for p,e in zip(q,E)),sum((i+1)*e*p for i,(p,e)in enumerate(zip(q,E))),E");L,I,E=S(x);B=None;exec("for k in range(N):\n a=(\"\\n# CLSIGMA_ZE_SELF_UPDATE nonce=%06d parent=%d rule=no_sha_spectral_residue_zero\\n\"%(k,I)).encode()\n l,j,e=S(x+a);r=j%M;d=min(r,M-r);c=(d,k,r,l,j,a.decode(),len(x+a))\n B=c if B is None or c<B else B\n if r==0:break");print(json.dumps({"P":"CLSIGMA/SELF_ZERO_ENTROPY_UPDATE_SEARCH/NO_PRESET_ZERO/NO_SHA/1","SelfPath":f,"SelfBytes":len(x),"PresetZeroDecimal":False,"KnownZeroTableUsed":False,"HashFunctionUsed":False,"ParentRho":{"real":"0.5","imag_form":"LogG_self","imag_approx":L},"ParentSpectralIndex":I,"Search":{"Target":"SpectralIndex % target_mod == 0","TargetMod":M,"MaxSteps":N,"StepsUsed":B[1]+1,"FoundExactZeroResidue":B[2]==0},"NextVersion":{"AppendixText":B[5],"Bytes":B[6],"SpectralResidue":B[2],"SpectralDistanceToZero":B[0],"rho_self":{"real":"0.5","imag_form":"LogG_next","imag_approx":B[3]},"SpectralIndex":B[4]},"CoordinateZE":int(B[2]==0),"ZE_info":int(B[2]==0),"SCL_Formal":int(B[2]==0),"ZetaZeroClaim":False,"PhysicalCosmicLaw":False,"RHProof":False,"Boundary":"protocol-defined update search; no preset zeta-zero values","UTC":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())},separators=(",",":")))' "$0" "$@"
